import { NavLink } from 'react-router-dom'
import { useAppStore } from '@/app/store'
import {
  ChevronLeft,
  ChevronRight,
  Home,
  ReceiptText,
  PackageSearch,
  Package,
  Users,
  Wrench,
  type LucideIcon,
} from 'lucide-react'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@radix-ui/react-tooltip'

const navItems = [
  { to: '/', icon: Home, label: 'Home' },
  { to: '/pos', icon: ReceiptText, label: 'POS' },
  { to: '/sales', icon: ReceiptText, label: 'Sales History' },
  { to: '/customers', icon: Users, label: 'Customers' },
  { to: '/repairs', icon: Wrench, label: 'Repairs' },
  { to: '/catalog/parts', icon: Package, label: 'Catalog' },
  { to: '/products/dst-search', icon: PackageSearch, label: 'Product Finder' },
]

export function SidePanel() {
  const { sidebarOpen, toggleSidebar } = useAppStore()

  return (
    <TooltipProvider delayDuration={0}>
      <aside
        className={`border-r bg-card transition-all duration-200 overflow-hidden ${
          sidebarOpen ? 'w-64' : 'w-12'
        }`}
      >
        {/* Collapse toggle — vertically centered in its area */}
        <div className="flex items-center justify-start px-2">
          {sidebarOpen && (
            <button
              onClick={toggleSidebar}
              className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"
            >
              <ChevronLeft size={16} />
              Collapse
            </button>
          )}
          {!sidebarOpen && (
            <div className="flex h-full flex-col justify-center py-4">
              <button
                onClick={toggleSidebar}
                className="flex items-center justify-center text-muted-foreground hover:text-foreground"
              >
                <ChevronRight size={16} />
              </button>
            </div>
          )}
        </div>
        <nav className="mt-4">
          <NavItemList items={navItems} sectionTitle="Main" sidebarOpen={sidebarOpen} />
        </nav>
      </aside>
    </TooltipProvider>
  )
}

function NavItem({ to, icon: Icon, label, sidebarOpen }: {
  to: string
  icon: LucideIcon
  label: string
  sidebarOpen: boolean
}) {
  return (
    <NavLink
      to={to}
      className={({ isActive }) =>
        `flex items-center gap-2 px-4 py-2 text-sm ${
          sidebarOpen
            ? `rounded ${
                isActive ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:bg-muted/50'
              }`
            : `${
                isActive ? 'border-l-[3px] border-primary pl-2 pr-4 text-primary font-medium'
                  : 'text-muted-foreground hover:text-foreground'
              }`
        }`
      }
    >
      <Tooltip>
        <TooltipTrigger asChild>
          <Icon size={16} />
        </TooltipTrigger>
        <TooltipContent side="right">
          <p>{label}</p>
        </TooltipContent>
      </Tooltip>
      {sidebarOpen && label}
    </NavLink>
  )
}

function NavItemList({ items, sectionTitle, sidebarOpen }: {
  items: { to: string; icon: LucideIcon; label: string }[]
  sectionTitle: string
  sidebarOpen: boolean
}) {
  return (
    <>
      {sidebarOpen && (
        <h2 className="px-4 text-xs font-semibold uppercase text-muted-foreground">
          {sectionTitle}
        </h2>
      )}
      <ul className="space-y-2">
        {items.map((item) => (
          <li key={item.to}>
            <NavItem to={item.to} icon={item.icon} label={item.label} sidebarOpen={sidebarOpen} />
          </li>
        ))}
      </ul>
      {sidebarOpen && <hr className="my-4 border-t border-muted" />}
    </>
  )
}

