import * as React from 'react'
import { describe, it, expect, vi } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { CurrencyInput } from '../CurrencyInput.js'

describe('CurrencyInput', () => {
  it('should display €12.50 when value is 1250 cents', () => {
    render(<CurrencyInput value={1250} onChange={() => {}} />)
    expect(screen.getByDisplayValue('€12.50')).toBeInTheDocument()
  })

  it('should display €0.00 when value is 0', () => {
    render(<CurrencyInput value={0} onChange={() => {}} />)
    expect(screen.getByDisplayValue('€0.00')).toBeInTheDocument()
  })

  it('should call onChange with cents when user types decimal euros', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={0} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '25.50' } })

    expect(handleChange).toHaveBeenCalledWith(2550)
  })

  it('should handle comma as decimal separator', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={0} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '12,50' } })

    expect(handleChange).toHaveBeenCalledWith(1250)
  })

  it('should format back to €X.XX on blur', () => {
    // Use a stateful wrapper to simulate parent updating value
    function TestWrapper() {
      const [cents, setCents] = React.useState(999)
      return <CurrencyInput value={cents} onChange={setCents} />
    }
    render(<TestWrapper />)

    const input = screen.getByRole('textbox')
    // Initial display should be formatted
    expect((input as HTMLInputElement).value).toBe('€9.99')

    fireEvent.blur(input)
    // After blur, value stays the same (already formatted)
    expect((input as HTMLInputElement).value).toBe('€9.99')
  })

  it('should reject negative values', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={0} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '-5' } })

    expect(handleChange).not.toHaveBeenCalled()
  })

  it('should handle empty input', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={100} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '' } })

    expect(handleChange).toHaveBeenCalledWith(0)
  })
})

import { create } from 'zustand'

// ---------------------------------------------------------------------------
// Global App Store (cross-cutting state)
//
// Flat structure — one level only. Each slice has its own setter.
// Features subscribe via selectors: useAppStore((s) => s.gamificationPoints)
// ---------------------------------------------------------------------------

export interface User {
  id: string
  name: string
  email: string
}

interface AppStoreState {
  // Sidebar (existing)
  sidebarOpen: boolean

  // User slice
  user: User | null

  // Theme slice
  theme: 'light' | 'dark'

  // Gamification slice
  gamificationPoints: number
}

interface AppStoreActions {
  // Sidebar
  setSidebarOpen: (open: boolean) => void
  toggleSidebar: () => void

  // User
  setUser: (user: User | null) => void

  // Theme
  setTheme: (theme: 'light' | 'dark') => void

  // Gamification
  addGamificationPoints: (points: number) => void
}

export type AppStore = AppStoreState & AppStoreActions

const initialState: AppStoreState = {
  sidebarOpen: true,
  user: null,
  theme: 'light',
  gamificationPoints: 0,
}

export const useAppStore = create<AppStore>((set) => ({
  ...initialState,

  // Sidebar
  setSidebarOpen: (open) => set({ sidebarOpen: open }),
  toggleSidebar: () => set((state) => ({ sidebarOpen: !state.sidebarOpen })),

  // User
  setUser: (user) => set({ user }),

  // Theme
  setTheme: (theme) => set({ theme }),

  // Gamification
  addGamificationPoints: (points) =>
    set((state) => ({ gamificationPoints: state.gamificationPoints + points })),
}))

